const ORDENES = { creada_en: "creada_en", prioridad: "prioridad", titulo: "titulo" };

export function leerPaginacion(query) {
  const pagina = Math.max(1, Number(query.pagina) || 1);
  const limite = Math.min(100, Math.max(1, Number(query.limite) || 20));
  const campo = (query.orden || "creada_en").replace(/^-/, "");
  if (!ORDENES[campo]) throw new ErrorHttp(400, "ORDEN_INVALIDO", `No se puede ordenar por ${campo}`);
  const direccion = query.orden?.startsWith("-") ? "DESC" : "ASC";
  return { pagina, limite, orden: `${ORDENES[campo]} ${direccion}` };
}

