// src/errores.js
export class ErrorHttp extends Error {
  constructor(estado, codigo, mensaje, detalles) {
    super(mensaje);
    this.estado = estado;
    this.codigo = codigo;
    this.detalles = detalles;
  }
}

/* Respuesta a un POST con datos inválidos (400)
{
  "error": {
    "codigo": "VALIDACION",
    "mensaje": "Revisa los datos enviados.",
    "detalles": [
      { "campo": "titulo", "mensaje": "Mínimo 3 caracteres" },
      { "campo": "prioridad", "mensaje": "Debe ser menor o igual a 3" }
    ]
  }
} */

// src/middlewares/validar.js
export const validar = (esquema) => (req, res, next) => {
  const r = esquema.safeParse(req.body);
  if (!r.success) {
    const detalles = r.error.issues.map((i) => ({ campo: i.path.join("."), mensaje: i.message }));
    throw new ErrorHttp(400, "VALIDACION", "Revisa los datos enviados.", detalles);
  }
  req.body = r.data;           // datos convertidos y sin campos extra
  next();
};

// src/rutas/tareas.js
rutasTareas.post("/", validar(esquemaTarea), ctrl.crear);

// src/middlewares/errores.js
export function manejarErrores(err, req, res, next) {
  const estado = err.estado ?? 500;
  if (estado >= 500) console.error(err);          // el detalle queda en el log
  res.status(estado).json({
    error: {
      codigo: err.codigo ?? "ERROR_INTERNO",
      mensaje: estado >= 500 ? "Ocurrió un error inesperado." : err.message,
      ...(err.detalles && { detalles: err.detalles }),
    },
  });
}

