export function validarId(req, res, next) {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    throw new ErrorHttp(400, "ID_INVALIDO", "El id debe ser un entero positivo.");
  }
  req.idRecurso = id;
  next();
}

rutasClientes.get("/:id", validarId, ctrl.obtener);

const TRADUCCIONES = {
  2627: [409, "DUPLICADO", "Ya existe un registro con esos datos."],
  2601: [409, "DUPLICADO", "Ya existe un registro con esos datos."],
  547: [409, "REFERENCIA", "El registro está relacionado con otros datos."],
};

export function manejarErrores(err, req, res, next) {
  if (TRADUCCIONES[err.number]) err = new ErrorHttp(...TRADUCCIONES[err.number]);
  if (err.code === "ESOCKET" || err.code === "ETIMEOUT") {
    const original = err;
    err = new ErrorHttp(503, "BD_NO_DISPONIBLE", "Servicio no disponible.");
    err.cause = original;
  }
  const estado = err.estado ?? 500;
  if (estado >= 500) console.error({ id: req.id, ruta: req.originalUrl, error: err.cause ?? err });
  res.status(estado).json({
    error: {
      codigo: err.codigo ?? "ERROR_INTERNO",
      mensaje: estado >= 500 ? "Ocurrió un error inesperado." : err.message,
      id: req.id,
    },
  });
}

