    @clienteId INT, @productoId INT, @cantidad INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRAN;

        UPDATE dbo.productos
        SET stock = stock - @cantidad
        WHERE producto_id = @productoId AND stock >= @cantidad;   -- atómico
        IF @@ROWCOUNT = 0
            THROW 50001, N'Stock insuficiente.', 1;

        DECLARE @pedido TABLE (pedido_id INT);
        INSERT INTO dbo.pedidos (cliente_id, total)
        OUTPUT INSERTED.pedido_id INTO @pedido
        SELECT @clienteId, precio * @cantidad FROM dbo.productos WHERE producto_id = @productoId;

        INSERT INTO dbo.pedido_lineas (pedido_id, producto_id, cantidad)
        SELECT pedido_id, @productoId, @cantidad FROM @pedido;

        COMMIT;
        SELECT pedido_id AS pedidoId FROM @pedido;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END;

