CREATE OR ALTER PROCEDURE dbo.transferir
    @origen INT, @destino INT, @monto DECIMAL(12,2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRAN;
        UPDATE dbo.cuentas SET saldo = saldo - @monto
        WHERE cuenta_id = @origen AND saldo >= @monto;
        IF @@ROWCOUNT = 0 THROW 50002, N'Saldo insuficiente.', 1;

        UPDATE dbo.cuentas SET saldo = saldo + @monto WHERE cuenta_id = @destino;
        IF @@ROWCOUNT = 0 THROW 50003, N'La cuenta destino no existe.', 1;

        INSERT INTO dbo.movimientos (origen_id, destino_id, monto)
        VALUES (@origen, @destino, @monto);
        COMMIT;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        THROW;
    END CATCH
END;

