import jwt from "jsonwebtoken";

export function autenticar(req, res, next) {
  const [tipo, token] = (req.get("Authorization") ?? "").split(" ");
  if (tipo !== "Bearer" || !token) {
    throw new ErrorHttp(401, "SIN_TOKEN", "Inicia sesión para continuar.");
  }
  try {
    const datos = jwt.verify(token, process.env.JWT_SECRETO, { algorithms: ["HS256"] });
    req.usuario = { id: Number(datos.sub), rol: datos.rol };
    next();
  } catch (err) {
    const codigo = err.name === "TokenExpiredError" ? "TOKEN_VENCIDO" : "TOKEN_INVALIDO";
    throw new ErrorHttp(401, codigo, "Inicia sesión de nuevo.");
  }
}

