async function cerrar(senal) {
  log.info({ senal }, "Cerrando de forma ordenada");
  servidor.close(async () => {          // deja de aceptar y espera las peticiones en curso
    await (await db()).close();          // cierra el pool de SQL Server
    process.exit(0);
  });
  setTimeout(() => process.exit(1), 10_000).unref();   // plazo máximo
}
